export interface CreditCardBrand {
  /**
   * The brand's display name, empty when the number matches no brand.
   */
  name: string;

  /**
   * Matches the number's leading digits.
   */
  pattern: RegExp;

  /**
   * The digit groups the number is displayed in.
   */
  groups: number[];

  /**
   * The valid number lengths, the usual one first.
   */
  lengths: number[];

  /**
   * The length of the security code (CVV/CVC) for this card brand.
   */
  securityCodeLength: number;

  /**
   * The icon representing the card brand.
   */
  icon?: React.ComponentType<IconProps>;

  /**
   * The brand's logo without the card background, shown on the card display.
   */
  logo?: React.ComponentType<SvgProps>;
}

