/**
 * Credit card fields (number, expiry date, security code and name on card)
 * with a card preview that follows what is entered.
 *
 * @example
 * ```tsx
 * <CreditCardInput>
 *   <CreditCardInput.Card bankName="Orbit Bank" />
 *   <Field name="cardNumber" required={true}>
 *     <Field.Label>Card number</Field.Label>
 *     <CreditCardInput.Number />
 *   </Field>
 *   <Field name="expiry" required={true}>
 *     <Field.Label>Expiry date</Field.Label>
 *     <CreditCardInput.Expiry placeholder="MM/YY" />
 *   </Field>
 *   <Field name="securityCode" required={true}>
 *     <Field.Label>Security code</Field.Label>
 *     <CreditCardInput.SecurityCode />
 *   </Field>
 *   <Field name="nameOnCard" required={true}>
 *     <Field.Label>Name on card</Field.Label>
 *     <CreditCardInput.Name />
 *   </Field>
 * </CreditCardInput>
 * ```
 *
 * @remarks
 * Each part is an `Input` that supplies its mask, parsing and validation to
 * the enclosing `Field`. The card number's value is its digits only and the expiry date's is
 * `MM/YY`. A `Field`'s own `validate` replaces the part's validation.
 */
export const CreditCardInput = withStaticProperties(CreditCardInputGroup, {
  Card: CreditCardInputCard,
  Number: CreditCardInputNumber,
  Expiry: CreditCardInputExpiry,
  SecurityCode: CreditCardInputSecurityCode,
  Name: CreditCardInputName
});

export type CreditCardInputProps = GetProps<typeof CreditCardInput>;
